/**
 * Carte interactive France & Europe reprise à l'identique de la maquette
 * accueil-desktop-refonte. Les tracés géographiques réels + les animations
 * (hub Tours, lignes bleues vers villes FR, pointillés dorés vers Europe,
 * points voyageurs animateMotion) sont injectés via innerHTML pour préserver
 * exactement le SVG source sans conversion JSX.
 */
export default function MapFranceEurope() {
  return (
    <section className="r4-map-section" id="reseau">
      <div className="r4-map-head">
        <div className="r4-eyebrow" style={{ justifyContent: "center" }}>
          <span className="r4-eyebrow-dot" />
          Notre présence
        </div>
        <h2>
          Un réseau qui couvre la <span className="r4-accent">France</span> &amp; l'Europe
        </h2>
        <p>
          Basés à Tours, nous intervenons partout en France sous 24/48h, et
          livrons vos véhicules dans toute l'Europe.
        </p>
      </div>

      <div className="r4-map-card">
        <svg
          className="r4-map-svg"
          viewBox="438 262 100 100"
          xmlns="http://www.w3.org/2000/svg"
          dangerouslySetInnerHTML={{ __html: MAP_SVG_INNER }}
        />

        <div className="r4-map-legend">
          <div className="r4-map-legend-item">
            <span className="r4-map-legend-dot" style={{ background: "#d9b54a", boxShadow: "0 0 8px #d9b54a" }} />
            Tours · Notre base
          </div>
          <div className="r4-map-legend-item">
            <span className="r4-map-legend-dot" style={{ background: "#4f8cff" }} />
            Villes desservies en France
          </div>
          <div className="r4-map-legend-item">
            <span className="r4-map-legend-dot" style={{ background: "#d9b54a" }} />
            Livraisons en Europe
          </div>
        </div>
      </div>
    </section>
  );
}
